CREATE TEMPORARY TABLE eventos(id INT PRIMARY KEY,payload JSON NOT NULL) ENGINE=InnoDB;
INSERT INTO eventos VALUES(1,'{"tipo":"compra","valor":25}');
SELECT id,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.tipo')) AS tipo,
 JSON_EXTRACT(payload,'$.valor') AS valor FROM eventos;

SET @itens='[{"sku":"A","qtd":2},{"sku":"B","qtd":1}]';
SELECT j.posicao,j.sku,j.qtd
FROM JSON_TABLE(@itens,'$[*]' COLUMNS(
 posicao FOR ORDINALITY,
 sku VARCHAR(20) PATH '$.sku' ERROR ON EMPTY,
 qtd INT PATH '$.qtd' ERROR ON EMPTY
)) AS j ORDER BY j.posicao;

