CREATE TEMPORARY TABLE contas(id INT PRIMARY KEY,saldo DECIMAL(10,2) NOT NULL) ENGINE=InnoDB;
INSERT INTO contas VALUES(1,100.00),(2,50.00);
START TRANSACTION;
UPDATE contas SET saldo=saldo-20 WHERE id=1;
SAVEPOINT apos_debito;
UPDATE contas SET saldo=saldo+99 WHERE id=2;
ROLLBACK TO SAVEPOINT apos_debito;
UPDATE contas SET saldo=saldo+20 WHERE id=2;
COMMIT;
SELECT id,saldo FROM contas ORDER BY id;

