#!/usr/bin/env bash
set -euo pipefail
# Pré-requisitos: bash, cliente mariadb e mariadb-dump 11.4.
# O administrador já criou mariadb_restore31 vazio e deu acesso ao aluno.
mariadb --user=aluno --password mariadb_forge <<'SQL'
DROP TABLE IF EXISTS mdb31_amostra;
CREATE TABLE mdb31_amostra(id INT PRIMARY KEY,valor DECIMAL(10,2)) ENGINE=InnoDB;
INSERT INTO mdb31_amostra VALUES(1,10.00),(2,25.00);
SQL
mariadb-dump --user=aluno --password --single-transaction mariadb_forge mdb31_amostra > backup31.sql
mariadb --user=aluno --password mariadb_restore31 < backup31.sql
mariadb --user=aluno --password --table mariadb_restore31 --execute='SELECT COUNT(*) AS linhas,SUM(valor) AS total FROM mdb31_amostra;'

SELECT @@server_id AS servidor,@@log_bin AS binlog_ativo;
SELECT @@global.gtid_binlog_pos AS produzido,@@global.gtid_slave_pos AS aplicado;
SHOW SLAVE STATUS;

SHOW GLOBAL VARIABLES LIKE 'wsrep_on';
SHOW GLOBAL STATUS WHERE Variable_name IN(
 'wsrep_cluster_status','wsrep_cluster_size','wsrep_local_state_comment','wsrep_ready','wsrep_connected'
);

