CREATE TEMPORARY TABLE pedidos(id INT PRIMARY KEY,referencia VARCHAR(30) NOT NULL UNIQUE,status VARCHAR(12) NOT NULL CHECK(status IN('aberto','pago','cancelado')),total DECIMAL(10,2) NOT NULL CHECK(total>=0)) ENGINE=InnoDB;
INSERT INTO pedidos VALUES(1,'REQ-A','aberto',50.00),(2,'REQ-B','pago',30.00);
